"""generated by derivations/proca_nonradial.py: projected linearised non-radial (polar, M = 0) equations of free
   Proca stars in the Regge-Wheeler gauge.  ROWS[name](r, omega, mu, Lam, f, E, X, alpha) returns a dict
   {(field, deriv): coefficient array}, deriv in "", "_t", "_r", "_tt", "_tr", "_rr";
   fields aR0 aI0 aR1 aI1 aR2 aI2 H0 H1 H2 K."""
import numpy as np
from numpy import pi, sqrt

ROWS = {}

def _Ptre(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR0', ''): ((Lam + mu**2*r**2)/(al_**2*r**2)) + z,
        ('aR0', '_r'): (2*(2*pi*E_**2*omega**2*r**2 + 2*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(X_**2*al_**6*mu**2*r)) + z,
        ('aR0', '_rr'): (-1/(X_**2*al_**2)) + z,
        ('aR1', '_t'): (-2*(2*pi*E_**2*omega**2*r**2 + 2*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(X_**2*al_**6*mu**2*r)) + z,
        ('aR1', '_tr'): (1/(X_**2*al_**2)) + z,
        ('aI1', ''): (-2*omega*(2*pi*E_**2*omega**2*r**2 + 2*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(X_**2*al_**6*mu**2*r)) + z,
        ('aI1', '_r'): (omega/(X_**2*al_**2)) + z,
        ('aR2', '_t'): (-Lam/(al_**2*r**2)) + z,
        ('aI2', ''): (-Lam*omega/(al_**2*r**2)) + z,
        ('H0', '_r'): (-1/2*E_/(X_**2*al_**2)) + z,
        ('H2', ''): (f_*mu**2/al_**2) + z,
        ('H2', '_r'): ((1/2)*E_/(X_**2*al_**2)) + z,
        ('K', '_r'): (-E_/(X_**2*al_**2)) + z,
    }
ROWS['Ptre'] = _Ptre

def _Ptim(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aI0', ''): ((Lam + mu**2*r**2)/(al_**2*r**2)) + z,
        ('aI0', '_r'): (2*(2*pi*E_**2*omega**2*r**2 + 2*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(X_**2*al_**6*mu**2*r)) + z,
        ('aI0', '_rr'): (-1/(X_**2*al_**2)) + z,
        ('aR1', ''): (2*omega*(2*pi*E_**2*omega**2*r**2 + 2*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(X_**2*al_**6*mu**2*r)) + z,
        ('aR1', '_r'): (-omega/(X_**2*al_**2)) + z,
        ('aI1', '_t'): (-2*(2*pi*E_**2*omega**2*r**2 + 2*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(X_**2*al_**6*mu**2*r)) + z,
        ('aI1', '_tr'): (1/(X_**2*al_**2)) + z,
        ('aR2', ''): (Lam*omega/(al_**2*r**2)) + z,
        ('aI2', '_t'): (-Lam/(al_**2*r**2)) + z,
        ('H1', ''): (E_*omega/(X_**2*al_**4)) + z,
    }
ROWS['Ptim'] = _Ptim

def _Prre(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR0', '_tr'): (1/(X_**2*al_**2)) + z,
        ('aI0', '_r'): (omega/(X_**2*al_**2)) + z,
        ('aR1', ''): (-(Lam*al_**2 + al_**2*mu**2*r**2 - omega**2*r**2)/(X_**2*al_**2*r**2)) + z,
        ('aR1', '_tt'): (-1/(X_**2*al_**2)) + z,
        ('aI1', '_t'): (-2*omega/(X_**2*al_**2)) + z,
        ('aR2', '_r'): (Lam/(X_**2*r**2)) + z,
        ('H0', '_t'): ((1/2)*E_/(X_**2*al_**2)) + z,
        ('H1', ''): (-f_*mu**2/(X_**2*al_**2)) + z,
        ('H2', '_t'): (-1/2*E_/(X_**2*al_**2)) + z,
        ('K', '_t'): (E_/(X_**2*al_**2)) + z,
    }
ROWS['Prre'] = _Prre

def _Prim(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR0', '_r'): (-omega/(X_**2*al_**2)) + z,
        ('aI0', '_tr'): (1/(X_**2*al_**2)) + z,
        ('aR1', '_t'): (2*omega/(X_**2*al_**2)) + z,
        ('aI1', ''): (-(Lam*al_**2 + al_**2*mu**2*r**2 - omega**2*r**2)/(X_**2*al_**2*r**2)) + z,
        ('aI1', '_tt'): (-1/(X_**2*al_**2)) + z,
        ('aI2', '_r'): (Lam/(X_**2*r**2)) + z,
        ('H0', ''): (-E_*omega/(X_**2*al_**2)) + z,
    }
ROWS['Prim'] = _Prim

def _Pthre(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR0', '_t'): (al_**(-2)) + z,
        ('aI0', ''): (omega/al_**2) + z,
        ('aR1', ''): ((4*pi*E_**2*r**2 - X_**2*al_**2 + al_**2)/(X_**2*al_**2*r)) + z,
        ('aR1', '_r'): (-1/X_**2) + z,
        ('aR2', ''): (-(al_*mu - omega)*(al_*mu + omega)/al_**2) + z,
        ('aR2', '_r'): (-(4*pi*E_**2*r**2 - X_**2*al_**2 + al_**2)/(X_**2*al_**2*r)) + z,
        ('aR2', '_tt'): (-1/al_**2) + z,
        ('aR2', '_rr'): (X_**(-2)) + z,
        ('aI2', '_t'): (-2*omega/al_**2) + z,
    }
ROWS['Pthre'] = _Pthre

def _Pthim(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR0', ''): (-omega/al_**2) + z,
        ('aI0', '_t'): (al_**(-2)) + z,
        ('aI1', ''): ((4*pi*E_**2*r**2 - X_**2*al_**2 + al_**2)/(X_**2*al_**2*r)) + z,
        ('aI1', '_r'): (-1/X_**2) + z,
        ('aR2', '_t'): (2*omega/al_**2) + z,
        ('aI2', ''): (-(al_*mu - omega)*(al_*mu + omega)/al_**2) + z,
        ('aI2', '_r'): (-(4*pi*E_**2*r**2 - X_**2*al_**2 + al_**2)/(X_**2*al_**2*r)) + z,
        ('aI2', '_tt'): (-1/al_**2) + z,
        ('aI2', '_rr'): (X_**(-2)) + z,
    }
ROWS['Pthim'] = _Pthim

def _Ett(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR0', ''): (-8*pi*f_*mu**2) + z,
        ('aR0', '_r'): (-8*pi*E_/X_**2) + z,
        ('aR1', '_t'): (8*pi*E_/X_**2) + z,
        ('aI1', ''): (16*pi*E_*omega/X_**2) + z,
        ('H0', ''): (-4*pi*(E_**2 + X_**2*f_**2*mu**2)/X_**2) + z,
        ('H2', ''): (-1/2*(-Lam*al_**2 - 2*al_**2 + 8*pi*f_**2*mu**2*r**2)/r**2) + z,
        ('H2', '_r'): (al_**2/(X_**2*r)) + z,
        ('K', ''): ((1/2)*al_**2*(Lam - 2)/r**2) + z,
        ('K', '_r'): ((1/2)*(4*pi*E_**2*al_**2*mu**2*r**2 + 4*pi*E_**2*omega**2*r**2 - X_**2*al_**4*mu**2 + 4*pi*X_**2*al_**2*f_**2*mu**4*r**2 - 5*al_**4*mu**2)/(X_**2*al_**2*mu**2*r)) + z,
        ('K', '_rr'): (-al_**2/X_**2) + z,
    }
ROWS['Ett'] = _Ett

def _Etr(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aI0', ''): (8*pi*E_*omega/al_**2) + z,
        ('aR1', ''): (-8*pi*f_*mu**2) + z,
        ('H1', ''): (-1/2*(-Lam*al_**2 + 16*pi*f_**2*mu**2*r**2)/(al_**2*r**2)) + z,
        ('H2', '_t'): (1/r) + z,
        ('K', '_t'): (-1/2*(4*pi*E_**2*al_**2*mu**2*r**2 - 4*pi*E_**2*omega**2*r**2 - X_**2*al_**4*mu**2 - 4*pi*X_**2*al_**2*f_**2*mu**4*r**2 + 3*al_**4*mu**2)/(al_**4*mu**2*r)) + z,
        ('K', '_tr'): (-1) + z,
    }
ROWS['Etr'] = _Etr

def _Err(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR0', ''): (-8*pi*X_**2*f_*mu**2/al_**2) + z,
        ('aR0', '_r'): (8*pi*E_/al_**2) + z,
        ('aR1', '_t'): (-8*pi*E_/al_**2) + z,
        ('H0', ''): ((1/2)*(8*pi*E_**2*r**2 + Lam*X_**2*al_**2 - 8*pi*X_**2*f_**2*mu**2*r**2)/(al_**2*r**2)) + z,
        ('H0', '_r'): (-1/r) + z,
        ('H1', '_t'): (2/(al_**2*r)) + z,
        ('H2', ''): (-X_**2*(al_**2 + 4*pi*f_**2*mu**2*r**2)/(al_**2*r**2)) + z,
        ('K', ''): (-1/2*X_**2*(Lam - 2)/r**2) + z,
        ('K', '_r'): (-1/2*(4*pi*E_**2*al_**2*mu**2*r**2 - 4*pi*E_**2*omega**2*r**2 - X_**2*al_**4*mu**2 - 4*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(al_**4*mu**2*r)) + z,
        ('K', '_tt'): (-X_**2/al_**2) + z,
    }
ROWS['Err'] = _Err

def _Etth(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR1', ''): (8*pi*E_/X_**2) + z,
        ('aR2', ''): (-8*pi*f_*mu**2) + z,
        ('aR2', '_r'): (-8*pi*E_/X_**2) + z,
        ('H1', ''): (-1/2*(4*pi*E_**2*r**2 - X_**2*al_**2 + al_**2)/(X_**2*al_**2*r)) + z,
        ('H1', '_r'): ((1/2)/X_**2) + z,
        ('H2', '_t'): (-1/2) + z,
        ('K', '_t'): (-1/2) + z,
    }
ROWS['Etth'] = _Etth

def _Erth(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR0', ''): (8*pi*E_/al_**2) + z,
        ('aR2', '_t'): (-8*pi*E_/al_**2) + z,
        ('H0', ''): (-1/4*(4*pi*E_**2*al_**2*mu**2*r**2 - 4*pi*E_**2*omega**2*r**2 - X_**2*al_**4*mu**2 - 4*pi*X_**2*al_**2*f_**2*mu**4*r**2 + 3*al_**4*mu**2)/(al_**4*mu**2*r)) + z,
        ('H0', '_r'): (1/2) + z,
        ('H1', '_t'): (-(1/2)/al_**2) + z,
        ('H2', ''): (-1/4*(4*pi*E_**2*al_**2*mu**2*r**2 - 4*pi*E_**2*omega**2*r**2 - X_**2*al_**4*mu**2 - 4*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(al_**4*mu**2*r)) + z,
        ('K', '_r'): (-1/2) + z,
    }
ROWS['Erth'] = _Erth

def _Ea(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR0', ''): (-8*pi*f_*mu**2*r**2/al_**2) + z,
        ('aR0', '_r'): (-8*pi*E_*r**2/(X_**2*al_**2)) + z,
        ('aR1', '_t'): (8*pi*E_*r**2/(X_**2*al_**2)) + z,
        ('H0', ''): (-1/2*(8*pi*E_**2*r**2 - Lam*X_**2*al_**2 + 8*pi*X_**2*f_**2*mu**2*r**2)/(X_**2*al_**2)) + z,
        ('H0', '_r'): ((1/4)*r*(12*pi*E_**2*al_**2*mu**2*r**2 - 4*pi*E_**2*omega**2*r**2 - 3*X_**2*al_**4*mu**2 - 4*pi*X_**2*al_**2*f_**2*mu**4*r**2 + al_**4*mu**2)/(X_**2*al_**4*mu**2)) + z,
        ('H0', '_rr'): (-1/2*r**2/X_**2) + z,
        ('H1', '_t'): (-1/2*r*(4*pi*E_**2*al_**2*mu**2*r**2 + 4*pi*E_**2*omega**2*r**2 - X_**2*al_**4*mu**2 + 4*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(X_**2*al_**6*mu**2)) + z,
        ('H1', '_tr'): (r**2/(X_**2*al_**2)) + z,
        ('H2', ''): (-1/2*(Lam*al_**2 + 8*pi*f_**2*mu**2*r**2)/al_**2) + z,
        ('H2', '_r'): ((1/4)*r*(4*pi*E_**2*al_**2*mu**2*r**2 - 4*pi*E_**2*omega**2*r**2 - X_**2*al_**4*mu**2 - 4*pi*X_**2*al_**2*f_**2*mu**4*r**2 - al_**4*mu**2)/(X_**2*al_**4*mu**2)) + z,
        ('H2', '_tt'): (-1/2*r**2/al_**2) + z,
        ('K', '_r'): (-1/2*r*(4*pi*E_**2*r**2 - X_**2*al_**2 - al_**2)/(X_**2*al_**2)) + z,
        ('K', '_tt'): (-1/2*r**2/al_**2) + z,
        ('K', '_rr'): ((1/2)*r**2/X_**2) + z,
    }
ROWS['Ea'] = _Ea

def _Eb(r, omega, mu, Lam, f_, E_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('H0', ''): (1/2) + z,
        ('H2', ''): (-1/2) + z,
    }
ROWS['Eb'] = _Eb
